-- Dashboard summary: the unread email count.
-- Applied to the Neon database on 2026-10-06 (direct endpoint). The server also creates the
-- index at start-up (server/storage.js). Nothing here changes or deletes rows.

-- Holds only the unread emails that are not in the bin (56 of about 7,000 on that day).
-- The condition is generated by dashboardEmailNotTrashedSql() and dashboardEmailUnreadSql()
-- in server/dashboard.js. PostgreSQL uses the index only while the dashboard query carries
-- the same condition, so change the two together and then rebuild the index.
create index concurrently if not exists app_emails_unread_idx
  on app_emails (received_at desc)
  where not ( coalesce(app_emails.data->'gmail_labels', '[]'::jsonb) ? 'TRASH' or coalesce(app_emails.data->>'dashboard_folder', '') = 'trash' or app_emails.data ? 'trashed_at' )
    and ( coalesce(app_emails.data->'gmail_labels', '[]'::jsonb) ? 'UNREAD' or coalesce(app_emails.data->'gmail_label_names', '[]'::jsonb) ? 'Unread' or coalesce(app_emails.data->>'is_read', '') = 'false' );

analyze app_emails;

-- To undo: drop index concurrently if exists app_emails_unread_idx;
-- The dashboard query keeps working without it, only slower.
